  size: string;
  top?: string;
  left?: string;
  right?: string;
  bottom?: string;
  delay: string;
  duration: string;
  anim: string;
}

const BLOBS: BlobConfig[] = [
  {
    color: "rgba(0, 162, 255, 0.42)",
    size: "72vmin",
    top: "-18%",
    left: "-12%",
    delay: "0s",
